@npc("Рыбак Ефим", skin="Notch")
class Fisher:
    @step("start")
    def on_click(self, player, npc):
        if player.has_flag("quest.fisher.done"):
            npc.say("Опять ты! Клёв сегодня хороший.")
            return
        npc.say("Принеси мне трёх треск — дам удочку получше.")
        npc.step("waiting", player)

    @step("waiting")
    def on_click(self, player, npc):
        if player.take("cod", 3):
            npc.animate("happy")
            npc.say("Вот это улов! Держи.")
            player.give(Item("fishing_rod", enchant={"lure": 3}))
            player.flag("quest.fisher.done", True)
            npc.step("start", player)
        else:
            npc.say("Пока не вижу трёх треск…")

@menu("<dark_green>Лавка", rows=3, glyph="<glyph:shop_bg>")
class Shop:
    goods = {11: ("bread", 16, 10), 13: ("cooked_beef", 8, 25), 15: ("golden_apple", 1, 200)}

    def build(self, player):
        return {slot: Item(m, n, lore=[f"<yellow>{price} монет"]) for slot, (m, n, price) in self.goods.items()}

    def click(self, player, slot, item):
        if slot in self.goods:
            m, n, price = self.goods[slot]
            if player.pay(price):
                player.give(Item(m, n))
                Sound(player.location, "entity.experience_orb.pickup")
            else:
                player.tell("<red>Не хватает монет")

records = Data("parkour_records")

@on("player enters area", area="parkour_start")
def start(event):
    event.player.flag("pk_start", server.time_ms)
    event.player.actionbar("<green>Время пошло!")

@on("player enters area", area="parkour_finish")
def finish(event):
    p = event.player
    t0 = p.flag("pk_start")
    if t0 is None:
        return
    sec = (server.time_ms - t0) / 1000
    p.unflag("pk_start")
    best = records.get(p.name)
    if best is None or sec < best:
        records[p.name] = sec
        Broadcast(f"<gold>{p.name}<yellow> — новый рекорд: {sec:.2f} с")
    else:
        p.tell(f"<gray>{sec:.2f} с (рекорд {best:.2f})")

